\title{Bidirectional Context-Aware Hierarchical Attention Network for Document Understanding}

\author{Jean-Baptiste Remy$^{1,\dagger}$ \hspace{0.5cm} Antoine J.-P. Tixier$^{1,\dagger}$ \hspace{0.5cm} Michalis Vazirgiannis$^{1,2}$\\
